      }
    } on AuthException catch (e) {
      if (mounted) setState(() => _error = e.message);
    } catch (_) {
      if (mounted) setState(() => _error = 'Could not sign in. Check Supabase SMS provider configuration.');
    } finally { if (mounted) setState(() => _busy = false); }
  }
